-- Part 7 (difficulty-uplift pass): online MCQ bank (comp_mcq_questions) hard (difficulty=3) items
-- for welding_inspector and radiography_interpreter. Same root cause/mechanism as
-- mcq_part7_hard_hse_site_supervisor_seed.sql. welding_inspector was at 10/48 hard (20.8%) and
-- radiography_interpreter at 9/43 (20.9%), both well under the bank-wide ~24% hard share and the
-- exam generator's 25% quota. welding_inspector already had hard items on most of its topics, so
-- this batch mixes 4 genuinely new topics (visual inspection acceptance limits, welding fume
-- safety, consumable/filler traceability, NCR pattern analysis) with distinct numeric/technical
-- angles on topics that already had one hard item (heat-input calculation for WPS/PQR, IIW carbon
-- equivalent calculation for metallurgy, NDE method selection, fusion-vs-porosity mechanism) so no
-- stem repeats. radiography_interpreter similarly adds 5 new-topic items (film density range,
-- DWDI technique selection, slag-vs-porosity appearance, interpretation methodology, root-defect
-- classification) plus 3 new numeric/scenario angles on topics that already had coverage
-- (geometric-unsharpness Ug=f*b/a calculation, borderline-indication film validity, Level
-- II/III interpreter disagreement). This adds 9 hard items to welding_inspector (-> ~33% hard)
-- and 8 to radiography_interpreter (-> ~33% hard).
-- Domain grounding: AWS D1.1 (heat input, visual acceptance, discontinuity classification), IIW
-- carbon-equivalent formula, AWS A5.1 (low-hydrogen electrode storage), API 1104 (filler
-- traceability, root-defect classification), OSHA 1910.252/ANSI Z49.1 (welding fume), ASME
-- Section V (NDE method selection, film density, geometric unsharpness, DWDI technique,
-- interpretation methodology), SNT-TC-1A (NDE personnel qualification hierarchy).
-- Anti-guessability: correct_option rotated 0..3 per row via the same technique as
-- supabase/seed/mcq_questions_seed.sql; no scenario shape repeats within this batch or the two
-- earlier Part 7 batches. Idempotent via (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'welding_inspector', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
from jsonb_array_elements($mcq$[
["TECHNICAL", "WPS/PQR", 3, "طبق فرمول استاندارد محاسبه انرژی ورودی جوشکاری (Heat Input = V×I×60 / (1000×سرعت جوشکاری بر میلی‌متر در دقیقه))، اگر ولتاژ قوس ۲۵ ولت، جریان جوشکاری ۲۰۰ آمپر و سرعت جوشکاری ۲۰۰ میلی‌متر بر دقیقه باشد، انرژی ورودی تقریبی کدام است؟", ["۰.۷۵ کیلوژول بر میلی‌متر", "۱.۵ کیلوژول بر میلی‌متر", "۳.۰ کیلوژول بر میلی‌متر", "۱۵.۰ کیلوژول بر میلی‌متر"], 1, "با استفاده از فرمول Heat Input = (V×I×60)/(1000×سرعت)، مقدار (۲۵×۲۰۰×۶۰)/(۱۰۰۰×۲۰۰) برابر ۱.۵ کیلوژول بر میلی‌متر است؛ این پارامتر باید در محدوده مجاز WPS برای کنترل ریزساختار و سختی منطقه متاثر از حرارت (HAZ) باقی بماند.", "AWS D1.1 / فرمول محاسبه Heat Input"],
["TECHNICAL", "متالورژی و جوش‌پذیری", 3, "طبق فرمول معادل کربن IIW (CE = C + Mn/6 + (Cr+Mo+V)/5 + (Ni+Cu)/15)، برای فولادی با C=۰.۲۰٪، Mn=۱.۲٪، Cr=۰.۳٪ و Ni=۰.۲٪ (بدون Mo/V/Cu)، معادل کربن تقریبی و پیامد اصلی آن کدام است؟", ["۰.۲۰٪؛ بدون ریسک خاص جوش‌پذیری", "حدود ۰.۴۷٪؛ ریسک بالاتر ترک هیدروژنی در HAZ و نیاز به پیش‌گرم/کنترل هیدروژن دقیق‌تر", "حدود ۰.۹۰٪؛ فولاد عملاً غیرقابل جوش", "۰.۰۵٪؛ فولاد بسیار نرم بدون نیاز به پیش‌گرم"], 1, "جمع مقادیر طبق فرمول IIW تقریباً ۰.۴۷٪ به‌دست می‌آید؛ معادل کربن بالاتر از حدود ۰.۴٪ معمولاً به معنای جوش‌پذیری دشوارتر و ریسک بیشتر ترک هیدروژنی در HAZ است که نیازمند پیش‌گرم و کنترل هیدروژن دقیق‌تر است.", "IIW Carbon Equivalent Formula / کنترل جوش‌پذیری فولاد"],
["TECHNICAL", "بازرسی چشمی جوش", 3, "طبق معیارهای پذیرش بازرسی چشمی جوش (مثل AWS D1.1)، بریدگی کناری (Undercut) در چه شرایطی معمولاً قابل قبول است؟", ["هیچ‌گاه قابل قبول نیست صرف‌نظر از عمق آن", "اگر عمق آن از حد مجاز مشخص‌شده در استاندارد/WPS (بر اساس ضخامت و نوع بارگذاری) فراتر نرود", "همیشه قابل قبول است چون فقط یک عیب ظاهری است", "فقط در جوش‌های افقی قابل قبول است"], 1, "بریدگی کناری تا عمق مشخصی که استاندارد مرجع (بر اساس ضخامت قطعه و نوع بارگذاری) تعیین می‌کند قابل قبول است؛ فراتر از آن باید تعمیر شود چون تمرکز تنش ایجاد می‌کند.", "AWS D1.1 Table 6.1 / معیار پذیرش بازرسی چشمی جوش"],
["SCENARIO", "ایمنی جوشکاری", 3, "جوشکاری باید در فضایی با تهویه طبیعی محدود انجام شود و دود جوشکاری (Welding Fume) به‌تدریج در محیط جمع می‌شود. اقدام درست کدام است؟", ["ادامه کار با ماسک ساده کاغذی معمولی بدون اقدام دیگر", "استفاده از تهویه موضعی مکانیکی (Local Exhaust Ventilation) یا حفاظت تنفسی مناسب همراه با پایش کیفیت هوا پیش و حین کار", "افزایش سرعت جوشکاری برای کاهش زمان مواجهه کارگر با دود", "باز گذاشتن یک درب کوچک به‌عنوان تنها اقدام کافی"], 1, "دود جوشکاری در فضای کم‌تهویه می‌تواند غلظت خطرناک فلزات سنگین و گازها ایجاد کند؛ تهویه موضعی مکانیکی مناسب یا حفاظت تنفسی به همراه پایش کیفیت هوا الزامی است.", "OSHA 1910.252(c) / ANSI Z49.1 (Welding Fume Control)"],
["TECHNICAL", "کنترل مصرفی‌های جوشکاری (الکترود/فیلر)", 3, "الکترودهای کم‌هیدروژن (Low-Hydrogen، مثل E7018) پس از باز شدن از بسته‌بندی اصلی باید چگونه نگهداری شوند تا کیفیت جوش حفظ شود؟", ["می‌توان آن‌ها را به مدت نامحدود در هوای آزاد کارگاه نگه داشت", "باید در کوره نگهدارنده (Holding Oven) با دمای کنترل‌شده نگهداری شوند و مدت مجاز مواجهه با هوای آزاد رعایت شود تا جذب رطوبت و ریسک ترک هیدروژنی افزایش نیابد", "باید در آب سرد نگهداری شوند تا خنک بمانند", "نگهداری آن‌ها تاثیری بر کیفیت جوش نهایی ندارد"], 1, "الکترودهای کم‌هیدروژن رطوبت را از هوا جذب می‌کنند که منبع هیدروژن اشباع‌شده و ریسک ترک هیدروژنی جوش را افزایش می‌دهد؛ باید در کوره نگهدارنده نگهداری و مدت مجاز مواجهه با هوای آزاد طبق مشخصات سازنده/WPS رعایت شود.", "AWS A5.1 / رویه نگهداری الکترود کم‌هیدروژن"],
["TECHNICAL", "مستندات، ITP و مدیریت NCR", 3, "چرا ثبت شماره ذوب (Heat Number) فلز پرکننده مصرفی روی گزارش جوش برای خطوط لوله سرویس بحرانی اهمیت دارد؟", ["فقط برای مصارف حسابداری انبار مصالح", "برای قابلیت ردیابی کامل (Traceability) خواص مکانیکی/شیمیایی فلز پرکننده در صورت بروز مشکل بعدی در سرویس", "چون رنگ الکترود مصرفی را مشخص می‌کند", "هیچ اهمیت فنی ندارد و فقط یک رویه اداری است"], 1, "ثبت شماره ذوب امکان ردیابی کامل خواص مکانیکی/شیمیایی فلز پرکننده مصرف‌شده در هر جوش را فراهم می‌کند که برای بررسی‌های آتی در صورت بروز خرابی سرویس حیاتی است.", "API 1104 / رویه ردیابی مصرفی‌های جوشکاری (Material Traceability)"],
["PROBLEM_SOLVING", "ناپیوستگی‌های جوش و علل آن", 3, "بازرسی چشمی نشان می‌دهد چند جوش پیاپی از یک جوشکار خاص طی یک شیفت دارای ناپیوستگی مشابه (تخلخل) هستند، در حالی که سایر جوشکاران روی همان پروژه مشکلی ندارند. رویکرد تحلیلی درست کدام است؟", ["فقط تعمیر جوش‌های معیوب بدون بررسی بیشتر", "بررسی علل احتمالی مرتبط با همان جوشکار/تجهیز (مثل کیفیت گاز محافظ، تنظیمات دستگاه یا مهارت) به‌عنوان یک NCR با ریشه‌یابی مشخص، نه یک اتفاق تصادفی پراکنده", "توقف کامل تولید همه جوشکاران بدون تمایز علت", "نادیده گرفتن الگو چون میزان تخلخل مشاهده‌شده جزئی است"], 1, "الگوی تکراری محدود به یک جوشکار/تجهیز خاص نشانه یک علت ریشه‌ای مشخص (تجهیز، مواد مصرفی یا مهارت) است که باید هدفمند در قالب NCR ریشه‌یابی شود، نه به‌عنوان اتفاق پراکنده صرفاً تعمیر و فراموش شود.", "رویه مدیریت NCR و ریشه‌یابی کیفیت جوش"],
["TECHNICAL", "انتخاب روش آزمون غیرمخرب (NDE)", 3, "برای شناسایی ترک‌های سطحی ریز در یک جوش فولاد کربنی، کدام روش آزمون غیرمخرب معمولاً حساسیت بیشتری نسبت به بازرسی چشمی ساده دارد و برای این هدف ترجیح داده می‌شود؟", ["رادیوگرافی (RT) به‌تنهایی", "آزمون ذرات مغناطیسی (MT) یا مایعات نافذ (PT) برای تشخیص ناپیوستگی‌های سطحی ریز", "آزمون سختی‌سنجی سطح جوش", "فقط اندازه‌گیری ابعادی با کولیس"], 1, "RT بیشتر برای ناپیوستگی‌های حجمی/داخلی مناسب است؛ برای ترک‌های سطحی ریز، روش‌های سطحی مانند MT (فولاد مغناطیسی) یا PT حساسیت بسیار بالاتری نسبت به بازرسی چشمی ساده دارند.", "ASME Section V / انتخاب روش NDE بر اساس نوع ناپیوستگی"],
["TECHNICAL", "ناپیوستگی‌های جوش و علل آن", 3, "کدام گزینه تفاوت اصلی «نفوذ ناقص» (Incomplete Fusion) را با «تخلخل» (Porosity) به‌درستی توصیف می‌کند؟", ["هر دو دقیقاً یک مکانیسم (گاز محبوس‌شده) دارند", "نفوذ ناقص یعنی عدم ذوب کامل بین فلز جوش و فلز پایه یا پاس قبلی (اغلب ناشی از آمپراژ ناکافی، سرعت بالا یا زاویه نادرست)، برخلاف تخلخل که ناشی از گاز محبوس‌شده حین انجماد حوضچه جوش است", "تخلخل فقط در جوشکاری زیرآبی رخ می‌دهد", "نفوذ ناقص فقط در جوش‌های عمودی رخ می‌دهد"], 1, "نفوذ ناقص ناشی از پارامترهای نادرست جوشکاری (آمپراژ کم، سرعت زیاد، زاویه نادرست) است که مانع ذوب کامل می‌شود، در حالی که تخلخل ناشی از گاز محبوس‌شده در حین انجماد حوضچه جوش است؛ این دو مکانیسم و ظاهر متفاوتی دارند.", "AWS D1.1 / طبقه‌بندی ناپیوستگی‌های جوش"]
]$mcq$::jsonb) with ordinality t(x, n)
cross join lateral (select ((((n - 1) % 4)::int - (x ->> 5)::int + 4) % 4) as k) r
on conflict (job_role, md5(stem_fa)) do nothing;

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'radiography_interpreter', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
from jsonb_array_elements($mcq$[
["TECHNICAL", "چگالی فیلم (Film Density)", 3, "طبق ASME Section V، محدوده قابل قبول چگالی فیلم رادیوگرافی در ناحیه مورد علاقه، معمولاً کدام است؟", ["۰.۵ تا ۱.۰", "۱.۸ تا ۴.۰ (بسته به نوع منبع پرتو و تجهیز مشاهده/چگالی‌سنج)", "۵.۰ تا ۶.۰", "چگالی فیلم هیچ محدوده استاندارد مشخصی ندارد"], 1, "طبق ASME V، چگالی فیلم قابل قبول در ناحیه مورد علاقه معمولاً در محدوده ۱.۸ تا ۴.۰ قرار دارد (با جزئیات بسته به نوع منبع پرتو و تجهیز مشاهده)؛ چگالی پایین‌تر باعث از دست رفتن حساسیت تشخیص می‌شود.", "ASME Section V, Article 2"],
["TECHNICAL", "انتخاب تکنیک رادیوگرافی", 3, "برای بازرسی جوش حلقوی یک لوله با قطر کوچک که امکان دسترسی به داخل لوله وجود ندارد، کدام تکنیک رادیوگرافی مناسب‌تر است؟", ["تک‌دیواره تک‌تصویر با منبع داخل لوله (SWSI با منبع داخلی)", "دودیواره دوتصویر (DWDI) با منبع و فیلم هر دو بیرون از لوله", "فقط بازرسی چشمی بدون انجام RT", "تکنیک پانورامیک با منبع مرکزی که فقط برای قطرهای بزرگ کاربرد دارد"], 1, "در لوله‌های قطر کوچک بدون دسترسی داخلی، تکنیک دودیواره دوتصویر (منبع و فیلم هر دو بیرون لوله؛ پرتو از هر دو دیواره عبور کرده و هر دو روی یک فیلم تصویر می‌شوند) روش عملی و رایج است.", "ASME Section V / ISO 17636-1 (DWDI Technique)"],
["TECHNICAL", "تمایز تخلخل از انکلوژن سرباره", 3, "در تفسیر فیلم رادیوگرافی، کدام ویژگی ظاهری معمولاً انکلوژن سرباره (Slag Inclusion) را از تخلخل کروی (Porosity) متمایز می‌کند؟", ["انکلوژن سرباره همیشه کاملاً کروی و یکنواخت است، درست مانند تخلخل", "انکلوژن سرباره اغلب شکل نامنظم، کشیده یا خطی دارد؛ تخلخل معمولاً کروی و با لبه‌های نرم است", "هیچ تفاوت ظاهری قابل تشخیصی در فیلم بین این دو وجود ندارد", "انکلوژن سرباره فقط در جوش‌های زیرآبی رخ می‌دهد"], 1, "انکلوژن سرباره در فیلم معمولاً شکل نامنظم، کشیده یا خطی و لبه‌های ناهموار دارد، در حالی که تخلخل به دلیل منشا گازی معمولاً شکل کروی و لبه نرم‌تری در تصویر نشان می‌دهد.", "ASME Section V / تفسیر الگوی ناپیوستگی در RT"],
